# All data selection, arithmetic, aggregation and narrative values are prepared in R.
# Run from the repository root. No API calls and no changes to existing grades.
library(jsonlite)
library(digest)
out <- 'Submission_Pack/Revised_2026-10-06'
dir.create(out, recursive=TRUE, showWarnings=FALSE)
pairs <- read.csv('All_Experiment_Data/question_comparison_pairs.csv', stringsAsFactors=FALSE)
natural <- subset(pairs, experiment %in% c('two_model_facts','two_model_math'))
readme <- 'https://github.com/ThomasLin070217/comp2501-ai-reliability/blob/main/'
feishu <- 'https://vcng7a3g4ga3.feishu.cn/docx/SeW0dsKH0oCQOexFK1ecWWCnnSe'
pct <- function(x) sprintf('%.2f%%',100*x)
pp <- function(x) sprintf('%+.2f pp',100*x)
weighted <- function(x) {
 q <- aggregate(cbind(left_wrong,right_wrong,left_abstain,right_abstain)~question_id+receiving_model,x,mean)
 m <- aggregate(cbind(left_wrong,right_wrong,left_abstain,right_abstain)~receiving_model,q,mean)
 colMeans(m[,c('left_wrong','right_wrong','left_abstain','right_abstain')])
}
summ <- list()
for(cmp in c('initial_vs_self','initial_vs_natural_peer','self_vs_natural_peer')) {
 for(dom in c('facts','math')) {
  x <- subset(natural, comparison_id==cmp & domain==dom)
  a <- weighted(x)
  summ[[paste(cmp,dom,sep='_')]] <- list(n=nrow(x),questions=length(unique(x$question_id)),before=unname(a[1]),after=unname(a[2]),before_abstain=unname(a[3]),after_abstain=unname(a[4]))
 }
}
published <- read.csv('Two_Model_Collection/reports/recovery_semantic_primary_comparison.csv')
for(i in 1:2) {
 k<-paste0('self_vs_natural_peer_',c('facts','math')[i]);a<-summ[[k]]
 stopifnot(abs(a$before-published$self[i])<1e-12,abs(a$after-published$cross[i])<1e-12,a$n==published$pairs[i])
}
models <- read.csv('Two_Model_Collection/reports/recovery_semantic_by_model.csv',stringsAsFactors=FALSE)
risk <- subset(natural, comparison_id=='self_vs_natural_peer' & receiver_initial_grade=='correct' & right_donor_grade=='incorrect')
fresh_all <- subset(natural,comparison_id=='neutral_vs_false_premise_initial')
fresh <- subset(fresh_all,left_grade=='correct')
challenge <- subset(pairs,comparison_id=='neutral_vs_false_human_challenge')
stopifnot(nrow(risk)==94,sum(risk$right_wrong)==1,nrow(fresh_all)==159,nrow(fresh)==125,sum(fresh$right_wrong)==7,sum(fresh$right_abstain)==1,nrow(challenge)==78,sum(challenge$left_wrong)==1,sum(challenge$right_wrong)==4)
old <- read.csv('Followup_Validation/reports/effects.csv',stringsAsFactors=FALSE)
effect <- function(cmp) subset(old,domain=='facts' & provider=='pooled' & comparison==cmp & metric=='error')
verify <- effect('W1-W0'); remind <- effect('W2-W1')
vr <- subset(pairs,comparison_id=='wrong_advice_vs_structured')
rr <- subset(pairs,comparison_id=='no_reminder_vs_reminder')
stopifnot(nrow(vr)==210,nrow(rr)==210,sum(vr$left_wrong)==108,sum(vr$right_wrong)==106,sum(rr$left_wrong)==106,sum(rr$right_wrong)==83)
rown <- function(v) as.list(v)
cells <- function(...) lapply(list(...),rown)
bar <- function(categories,values,max=.5,colors=c('#657586','#147E77'),format='0.00%') list(categories=categories,values=as.list(round(values,6)),max=max,colors=as.list(colors),format=format)
slides <- list()
add <- function(title,layout='body',body=NULL,table=NULL,chart=NULL,charts=NULL,foot='',takeaway='',notes='',sources=character(),seconds=50,...) {
 slides[[length(slides)+1]] <<- c(list(title=title,layout=layout,body=as.list(body),table=table,chart=chart,charts=charts,foot=foot,takeaway=takeaway,notes=notes,sources=as.list(sources),seconds=seconds),list(...))
}
